from langflow.custom import Component
from langflow.inputs import HandleInput, MessageTextInput
from langflow.template import Output
from langflow.field_typing import Tool, Embeddings
from langchain.tools.base import BaseTool, StructuredTool
from langflow.schema import Data

class ToolkitComponent(Component):
    display_name = "Toolkit"
    description = "Combines multiple tools into a single list of tools."
    icon = "pocket-knife"

    inputs = [
        HandleInput(
            name="tools",
            display_name="Tools",
            input_types=["Tool"],
            info="List of tools to combine.",
            is_list=True,
        ),
    ]

    outputs = [
        Output(display_name="Tools", name="generated_tools", method="generate_toolkit"),
        Output(display_name="Tool Data", name="tool_data", method="generate_tool_data"),
    ]

    def generate_toolkit(self) -> List[BaseTool]:
        combined_tools = []
        name_count = {}
        for index, tool in enumerate(self.tools):
            self.log(f"Processing tool {index}: {type(tool)}")
            if isinstance(tool, (BaseTool, StructuredTool)):
                processed_tool = tool
            elif hasattr(tool, 'build_tool'):
                processed_tool = tool.build_tool()
            else:
                self.log(f"Unsupported tool type: {type(tool)}. Attempting to process anyway.")
                processed_tool = tool

            original_name = getattr(processed_tool, 'name', f"UnnamedTool_{index}")
            self.log(f"Original tool name: {original_name}")

            if original_name not in name_count:
                name_count[original_name] = 0
                final_name = original_name
            else:
                name_count[original_name] += 1
                final_name = f"{original_name}_{name_count[original_name]}"

            if hasattr(processed_tool, 'name'):
                processed_tool.name = final_name

            self.log(f"Final tool name: {final_name}")

            if isinstance(processed_tool, StructuredTool) and hasattr(processed_tool, 'args_schema'):
                processed_tool.args_schema.name = f"{final_name}_Schema"

            combined_tools.append(processed_tool)

        debug_info = "\n".join([f"Tool {i}: {getattr(tool, 'name', f'UnnamedTool_{i}')} (Original: {getattr(tool, '_original_name', 'N/A')}) - Type: {type(tool)}" for i, tool in enumerate(combined_tools)])
        self.log("Final toolkit composition:")
        self.log(debug_info)


        self.status = combined_tools
        return combined_tools

    def generate_tool_data(self) -> List[Data]:
        tool_data = []
        for tool in self.generate_toolkit():
            tool_data.append(Data(
                data={
                    "name": getattr(tool, 'name', 'Unnamed Tool'),
                    "description": getattr(tool, 'description', 'No description available')
                }
            ))
        return tool_data","fileTypes":[],"file_path":"","password":false,"name":"code","advanced":true,"dynamic":true,"info":"","load_from_db":false,"title_case":false}},"description":"Combines multiple tools into a single list of tools.","icon":"pocket-knife","base_classes":["BaseTool","Data"],"display_name":"Toolkit","documentation":"","custom_fields":{},"output_types":[],"pinned":false,"conditional_paths":[],"frozen":false,"outputs":[{"types":["BaseTool"],"selected":"BaseTool","name":"generated_tools","display_name":"Tools","method":"generate_toolkit","value":"__UNDEFINED__","cache":true},{"types":["Data"],"selected":"Data","name":"tool_data","display_name":"Tool Data","method":"generate_tool_data","value":"__UNDEFINED__","cache":true,"hidden":true}],"field_order":["tools"],"beta":false,"edited":true,"lf_version":"1.0.17"},"id":"ToolkitComponent-2lNG0"},"selected":false,"width":384,"height":292,"dragging":false,"positionAbsolute":{"x":1731.8884789245508,"y":1378.7846304343796}},{"id":"OpenAIModel-BJWIg","type":"genericNode","position":{"x":1718.9773974162958,"y":603.4642741725065},"data":{"type":"OpenAIModel","node":{"template":{"_type":"Component","api_key":{"load_from_db":true,"required":false,"placeholder":"","show":true,"name":"api_key","value":"","display_name":"OpenAI API Key","advanced":false,"input_types":["Message"],"dynamic":false,"info":"The OpenAI API Key to use for the OpenAI model.","title_case":false,"password":true,"type":"str","_input_type":"SecretStrInput"},"code":{"type":"code","required":true,"placeholder":"","list":false,"show":true,"multiline":true,"value":"import operator
